-- References to existing ledger expenses only. No agreements or payment entries are created.
begin;
create table if not exists public.cb_experience_cost_links(item_id uuid primary key references public.cb_experience_items on delete cascade,expense_id uuid references public.cb_shared_expenses on delete restrict,item_revision bigint not null,revision bigint not null default 1,updated_at timestamptz not null default now());
create table if not exists public.cb_experience_cost_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_cost_history(item_id uuid not null references public.cb_experience_items on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(item_id,revision));
alter table public.cb_experience_cost_links enable row level security;alter table public.cb_experience_cost_writes enable row level security;alter table public.cb_experience_cost_history enable row level security;
revoke all on public.cb_experience_cost_links,public.cb_experience_cost_writes,public.cb_experience_cost_history from public,anon,authenticated;
create or replace function public.cb_experience_budget(p_event uuid,p_search text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ev public.cb_project_events;result jsonb;begin
 select * into ev from public.cb_project_events where id=p_event;if ev.id is null or not coalesce(public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Celebration access required' using errcode='42501';end if;
 if not coalesce(public.cb_project_access(ev.project_id,'finance'),false) then return jsonb_build_object('available',false,'can_link',false,'items','[]'::jsonb,'totals','[]'::jsonb,'choices','[]'::jsonb);end if;
 if p_search is null or length(p_search)>100 then raise exception 'Search using up to 100 characters';end if;
 with refs as (
 select l.item_id,l.revision link_revision,l.item_revision reviewed_item_revision,e.id expense_id,e.title,e.currency,e.revision expense_revision,coalesce(e.settlement_total,e.agreed_total) commitment,coalesce((select sum(case when p.kind='Payment' then p.amount else -p.amount end) from public.cb_shared_payments p where p.expense_id=e.id),0) net_paid,b.status booking_status,b.event_id booking_event from public.cb_experience_cost_links l join public.cb_experience_items i on i.id=l.item_id join public.cb_shared_expenses e on e.id=l.expense_id left join public.cb_vendor_bookings b on b.id=e.booking_id where i.event_id=ev.id and e.project_id=ev.project_id
 ),unique_expenses as(select distinct expense_id,currency,commitment,net_paid from refs)
 select jsonb_build_object('available',true,'can_link',public.cb_project_access(ev.project_id,'write'),'event',ev.id,'event_revision',ev.revision,'project',ev.project_id,'totals',(select coalesce(jsonb_agg(to_jsonb(t) order by currency),'[]') from (select currency,count(*) expenses,sum(commitment) committed,sum(net_paid) net_paid,sum(commitment-net_paid) balance from unique_expenses group by currency) t),'items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'title',i.data->>'title','status',i.data->>'status','revision',i.revision,'link_revision',coalesce(l.revision,0),'expense',case when r.expense_id is null then null else jsonb_build_object('id',r.expense_id,'title',r.title,'currency',r.currency,'revision',r.expense_revision,'commitment',r.commitment,'net_paid',r.net_paid,'balance',r.commitment-r.net_paid,'booking_status',r.booking_status,'scope_changed',r.booking_event is not null and r.booking_event<>ev.id,'source_changed',r.reviewed_item_revision<>i.revision,'used_other_events',exists(select 1 from public.cb_experience_cost_links z join public.cb_experience_items zi on zi.id=z.item_id where z.expense_id=r.expense_id and zi.event_id<>ev.id)) end) order by i.data->>'title',i.id),'[]') from public.cb_experience_items i left join public.cb_experience_cost_links l on l.item_id=i.id left join refs r on r.item_id=i.id where i.event_id=ev.id),'choices',(select coalesce(jsonb_agg(to_jsonb(x) order by x.title,x.id),'[]') from (select e.id,e.title,e.currency,e.revision,coalesce(e.settlement_total,e.agreed_total) total from public.cb_shared_expenses e left join public.cb_vendor_bookings b on b.id=e.booking_id where e.project_id=ev.project_id and (b.event_id is null or b.event_id=ev.id) and coalesce(b.status,'')<>'Cancelled' and strpos(lower(e.title),lower(p_search))>0 order by e.title,e.id limit 100) x)) into result;return result;
end;$$;
create or replace function public.cb_save_experience_cost(p_event uuid,p_event_revision bigint,p_item uuid,p_item_revision bigint,p_revision bigint,p_client uuid,p_expense uuid,p_expense_revision bigint,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare ev public.cb_project_events;i public.cb_experience_items;l public.cb_experience_cost_links;e public.cb_shared_expenses;b public.cb_vendor_bookings;w public.cb_experience_cost_writes;payload jsonb;result jsonb;begin
 select * into ev from public.cb_project_events where id=p_event;perform 1 from public.cb_projects where id=ev.project_id for update;select * into ev from public.cb_project_events where id=p_event for update;
 if ev.id is null or not coalesce(public.cb_project_access(ev.project_id,'write') and public.cb_project_access(ev.project_id,'finance') and public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Celebration planning and financial access required' using errcode='42501';end if;
 payload=jsonb_build_object('event',p_event,'event_revision',p_event_revision,'item',p_item,'item_revision',p_item_revision,'revision',p_revision,'expense',p_expense,'expense_revision',p_expense_revision,'confirm',p_confirm);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_cost_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original expense connection' using errcode='PT409';end if;return w.response;end if;
 if p_confirm is distinct from true then raise exception 'Review and confirm this whole-expense connection';end if;
 if ev.revision is distinct from p_event_revision then raise exception 'The celebration changed. Refresh before reviewing costs.' using errcode='PT409';end if;
 select * into i from public.cb_experience_items where id=p_item and event_id=p_event for update;if i.id is null then raise exception 'Choose a service in this celebration' using errcode='42501';end if;if i.revision is distinct from p_item_revision then raise exception 'The service changed. Refresh before reviewing costs.' using errcode='PT409';end if;
 if p_expense is not null then if i.data->>'status'='Cancelled' then raise exception 'Reopen this cancelled service before connecting an expense';end if;select * into e from public.cb_shared_expenses where id=p_expense and project_id=ev.project_id for update;if e.id is null then raise exception 'Choose an expense in this wedding' using errcode='42501';end if;if e.revision is distinct from p_expense_revision then raise exception 'The ledger changed. Refresh before connecting this expense.' using errcode='PT409';end if;select * into b from public.cb_vendor_bookings where id=e.booking_id;if b.status='Cancelled' or b.event_id is not null and b.event_id<>ev.id then raise exception 'Review the booking celebration and status in the ledger first';end if;
 elsif p_expense_revision is not null then raise exception 'Clear the expense revision when removing a connection';end if;
 select * into l from public.cb_experience_cost_links where item_id=p_item for update;if coalesce(l.revision,0) is distinct from p_revision then raise exception 'Another teammate changed this expense connection. Refresh first.' using errcode='PT409';end if;
 insert into public.cb_experience_cost_links(item_id,expense_id,item_revision) values(p_item,p_expense,i.revision) on conflict(item_id) do update set expense_id=excluded.expense_id,item_revision=excluded.item_revision,revision=public.cb_experience_cost_links.revision+1,updated_at=now() returning * into l;
 insert into public.cb_experience_cost_history values(l.item_id,l.revision,auth.uid(),to_jsonb(l),now());result=jsonb_build_object('saved',true,'revision',l.revision);insert into public.cb_experience_cost_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
revoke all on function public.cb_experience_budget(uuid,text),public.cb_save_experience_cost(uuid,bigint,uuid,bigint,bigint,uuid,uuid,bigint,boolean) from public,anon,authenticated;
grant execute on function public.cb_experience_budget(uuid,text),public.cb_save_experience_cost(uuid,bigint,uuid,bigint,bigint,uuid,uuid,bigint,boolean) to authenticated;
notify pgrst,'reload schema';commit;
